  'azure-nodejs',
  'google-nodejs',
  'kubeless-python',
  'kubeless-nodejs',
  'openwhisk-nodejs',
  'openwhisk-php',
  'openwhisk-python',
  'openwhisk-swift',
  'spotinst-nodejs',
  'spotinst-python',
