  'hello-world',
];

const humanReadableTemplateList = `${validTemplates.slice(0, -1)
  .map((template) => `"${template}"`).join(', ')} and "${validTemplates.slice(-1)}"`;

class Create {
  constructor(serverless, options) {
    this.serverless = serverless;
    this.options = options;

    this.commands = {
      create: {
        usage: 'Create new Serverless service',
        lifecycleEvents: [
          'create',
        ],
        options: {
          template: {
            usage: `Template for the service. Available templates: ${humanReadableTemplateList}`,
            shortcut: 't',
          },
          'template-url': {
            usage: 'Template URL for the service. Supports: GitHub, BitBucket',
            shortcut: 'u',
          },
          'template-path': {
            usage: 'Path to a local template directory for the service',
          },
          path: {
            usage: 'The path where the service should be created (e.g. --path my-service)',
            shortcut: 'p',
          },
          name: {
            usage: 'Name for the service. Overwrites the default name of the created service.',
            shortcut: 'n',
          },
        },
      },
    };

    this.hooks = {
      'create:create': () => BbPromise.bind(this)
        .then(this.create),
    };
  }

  create() {
    this.serverless.cli.log('Generating boilerplate...');

    if ('template' in this.options) {
      this.createFromTemplate();
    } else if ('template-path' in this.options) {
      this.createFromPath();
    } else if ('template-url' in this.options) {
      return download.downloadTemplateFromRepo(
        this.options['template-url'],
        this.options.name,
        this.options.path
      )
        .then(dirName => {
          const message = [
            `Successfully installed "${dirName}" `,
            `${this.options.name && this.options.name !== dirName ? `as "${dirName}"` : ''}`,
          ].join('');

          this.serverless.cli.log(message);

          userStats.track('service_created', {
            template: this.options.template,
            serviceName: this.options.name,
          });
        })
        .catch(err => {
          throw new this.serverless.classes.Error(err);
        });
    } else {
      const errorMessage = [
        'You must either pass a template name (--template), a URL (--template-url) ',
        'or a local path (--template-path).',
      ].join('');
      throw new this.serverless.classes.Error(errorMessage);
    }
    return BbPromise.resolve();
  }

  createFromPath() {
    const templatePath = _.toString(this.options['template-path']);
    if (!templatePath || !this.serverless.utils.dirExistsSync(path.resolve(templatePath))) {
      const errorMessage = [
        `The template path "${templatePath}" does not exist or is not a directory.`,
      ].join('');
      throw new this.serverless.classes.Error(errorMessage);
    }

    const templateSrcDir = path.resolve(templatePath);
    const boilerplatePath = _.toString(this.options.path);
    const serviceName = _.toString(this.options.name);
    const servicePath = boilerplatePath ? path.resolve(boilerplatePath) : process.cwd();

    if (boilerplatePath && fse.existsSync(servicePath)) {
      const errorMessage = [
        `The directory "${servicePath}" already exists, and serverless will not overwrite it.`,
      ].join('');
      throw new this.serverless.classes.Error(errorMessage);
    }

    const templateFullFilePaths = this.serverless.utils.walkDirSync(templateSrcDir);
    if (!boilerplatePath) {
      templateFullFilePaths.forEach((filePath) => {
        const relativeFilePath = path.relative(templateSrcDir, filePath);
        const targetPath = path.join(servicePath, relativeFilePath);
        if (fse.existsSync(targetPath)) {
          const errorMessage = [
            `The file "${relativeFilePath}" already exists, and serverless will not overwrite it. `,
            'Move the file and try again if you want serverless to write a new file',
          ].join('');

          throw new this.serverless.classes.Error(errorMessage);
        }
      });
    } else {
      fse.mkdirsSync(servicePath);
    }

    try {
      this.serverless.utils.copyDirContentsSync(templateSrcDir, servicePath);
    } catch (err) {
      const errorMessage = [
        'Error unable to create a service in this directory. ',
        'Please check that you have the required permissions to write to the directory',
      ].join('');

      throw new this.serverless.classes.Error(errorMessage);
    }

    const newServiceName = serviceName || (boilerplatePath && path.basename(servicePath));
    if (newServiceName) renameService(newServiceName, servicePath);

    userStats.track('service_created', {
      template: templatePath,
      serviceName,
    });

    this.serverless.cli.asciiGreeting();
    this.serverless.cli
      .log(`Successfully generated boilerplate from local template: "${templatePath}"`);
  }

