      const templatePath = testUtils.getTmpDirPath();
      fse.mkdirsSync(templatePath);
      fse.writeFileSync(path.join(templatePath, 'serverless.yml'), 'service: template-name\n');
      fse.writeFileSync(path.join(templatePath, 'package.json'),
        JSON.stringify({ name: 'template-name' }));
      fse.mkdirsSync(path.join(templatePath, 'nested'));
      fse.writeFileSync(path.join(templatePath, 'nested', 'file.txt'), 'template content');

      process.chdir(tmpDir);
      create.options = {
        'template-path': templatePath,
        path: 'new-service',
        name: 'custom-service',
      };

      return create.create().then(() => {
        const serviceDir = path.join(tmpDir, 'new-service');
        expect(fs.readFileSync(path.join(serviceDir, 'nested', 'file.txt'), 'utf8'))
          .to.equal('template content');
        expect(fs.readFileSync(path.join(serviceDir, 'serverless.yml'), 'utf8'))
          .to.equal('service: custom-service\n');
        expect(JSON.parse(fs.readFileSync(path.join(serviceDir, 'package.json'), 'utf8')).name)
          .to.equal('custom-service');
      });
    });

